def get_components(grid, color):
    visited = set()
    components = []
    grid_r = len(grid)
    grid_c = len(grid[0]) if grid else 1

    for row_idx in range(grid_r):
        for col_idx in range(grid_c):
            if grid[row_idx][col_idx] == color and (row_idx, col_idx) not in visited:
                component = []
                stack = [(row_idx, col_idx)]
                while stack:
                    nr, nc = stack.pop()
                    if (nr, nc) in visited:
                        continue
                    visited.add((nr, nc))
                    component.append((nr, nc))
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nnr, nnc = nr + dr, nc + dc
